def solve():
    # Wait, let's check if there's any other combination of q_i that gives a larger sum.
    # We have the following constraints:
    # q_0 <= 202
    # q_1 <= q_0 / 10
    # q_2 <= (q_0 + q_1) / 10
    # q_3 <= (q_0 + q_1 + q_2) / 10
    # q_4 <= (q_1 + q_2 + q_3) / 10
    # q_5 <= (q_2 + q_3 + q_4) / 10
    # q_6 <= (q_3 + q_4 + q_5) / 10
    # q_7 <= (q_4 + q_5 + q_6) / 10
    # q_8 <= (q_5 + q_6 + q_7) / 10

    # This is a linear programming problem. Since the coefficients are all positive,
    # the maximum will be at the "upper bound" of the constraints.
    # Let's just use a small brute force to be sure.
    max_q_sum = 0
    for q0 in range(203):
        for q1 in range(q0 // 10 + 1):
            for q2 in range((q0 + q1) // 10 + 1):
                for q3 in range((q0 + q1 + q2) // 10 + 1):
                    for q4 in range((q1 + q2 + q3) // 10 + 1):
                        for q5 in range((q2 + q3 + q4) // 10 + 1):
                            for q6 in range((q3 + q4 + q5) // 10 + 1):
                                for q7 in range((q4 + q5 + q6) // 10 + 1):
                                    for q8 in range((q5 + q6 + q7) // 10 + 1):
                                        max_q_sum = max(max_q_sum, q0+q1+q2+q3+q4+q5+q6+q7+q8)
    print(max_q_sum)

solve()
